     6	import java.sql.Connection;
     7	import java.sql.SQLException;
     8	import java.sql.Statement;
     9	
    10	public class Database implements AutoCloseable {
    11	    @FunctionalInterface
    12	    public interface Work<T> {
    13	        T run(Connection connection) throws SQLException;
    14	    }
    15	
    16	    private final HikariDataSource dataSource;
    17	
    18	    public Database(String url, String user, String password) {
    19	        HikariConfig config = new HikariConfig();
    20	        config.setJdbcUrl(url);
    21	        config.setUsername(user);
    22	        config.setPassword(password);
    23	        config.setMaximumPoolSize(10);
    24	        config.setInitializationFailTimeout(60_000); // espera o banco subir
    25	        this.dataSource = new HikariDataSource(config);
    26	        createSchema();
    27	    }
    28	
    29	    private void createSchema() {
    30	        inTransaction(c -> {
    31	            try (Statement s = c.createStatement()) {
    32	                s.execute("""
    33	                        CREATE TABLE IF NOT EXISTS reservations (
    34	                            id BIGSERIAL PRIMARY KEY,
    35	                            room_number INT NOT NULL,
    36	                            guest_name TEXT NOT NULL,
    37	                            guest_email TEXT NOT NULL,
    38	                            guest_cpf TEXT NOT NULL,
    39	                            check_in DATE NOT NULL,
    40	                            check_out DATE NOT NULL,
    41	                            guests INT NOT NULL,
    42	                            rate_plan TEXT NOT NULL,
    43	                            nights INT NOT NULL,
    44	                            subtotal NUMERIC(12,2) NOT NULL,
    45	                            discount NUMERIC(12,2) NOT NULL,
    46	                            total NUMERIC(12,2) NOT NULL,
    47	                            status TEXT NOT NULL,
    48	                            amount_paid NUMERIC(12,2) NOT NULL,
    49	                            refund NUMERIC(12,2)
    50	                        )""");
    51	                s.execute("""
    52	                        CREATE TABLE IF NOT EXISTS messages (
    53	                            id BIGSERIAL PRIMARY KEY,
    54	                            channel TEXT NOT NULL,
    55	                            recipient TEXT NOT NULL,
    56	                            subject TEXT NOT NULL,
    57	                            body TEXT NOT NULL
    58	                        )""");
    59	            }
    60	            return null;
    61	        });
    62	    }
    63	
    64	    /** Executa o trabalho numa transação: tudo é gravado junto ou nada é. */
    65	    public <T> T inTransaction(Work<T> work) {
    66	        try (Connection c = dataSource.getConnection()) {
    67	            c.setAutoCommit(false);
    68	            try {
    69	                T result = work.run(c);
    70	                c.commit();
    71	                return result;
    72	            } catch (Throwable e) {
    73	                c.rollback();
    74	                throw e;
    75	            }
    76	        } catch (SQLException e) {
    77	            throw new IllegalStateException("Erro de banco de dados", e);
    78	        }
    79	    }
    80	
    81	    @Override
    82	    public void close() {
    83	        dataSource.close();
    84	    }
    85	}
