    12	import java.time.LocalDate;
    13	import java.time.YearMonth;
    14	import java.time.format.DateTimeParseException;
    15	import java.util.Map;
    16	
    17	/** A interface HTTP combinada com o site. */
    18	public class Routes {
    19	    private static final String CSV = "text/csv; charset=utf-8";
    20	
    21	    private final ObjectMapper json = new ObjectMapper()
    22	            .registerModule(new JavaTimeModule())
    23	            .disable(SerializationFeature.WRITE_DATES_AS_TIMESTAMPS)
    24	            .disable(DeserializationFeature.FAIL_ON_UNKNOWN_PROPERTIES);
    25	    private final Rooms rooms;
    26	    private final ReservationService service;
    27	    private final ReportService reports;
    28	
    29	    public Routes(Rooms rooms, ReservationService service, ReportService reports) {
    30	        this.rooms = rooms;
    31	        this.service = service;
    32	        this.reports = reports;
    33	    }
    34	
    35	    public void register(Javalin app) {
    36	        app.get("/rooms", ctx -> reply(ctx, 200, rooms.all()));
    37	        app.post("/reservations", ctx -> reply(ctx, 201, service.create(parseNewReservation(ctx.body()))));
    38	        app.get("/reservations/{id}", ctx -> reply(ctx, 200, service.get(ctx.pathParam("id"))));
    39	        app.post("/reservations/{id}/confirmation", ctx -> reply(ctx, 200, service.confirm(ctx.pathParam("id"))));
    40	        app.post("/reservations/{id}/cancellation", ctx -> reply(ctx, 200, service.cancel(ctx.pathParam("id"))));
    41	        app.post("/reservations/{id}/check-in", ctx -> reply(ctx, 200, service.checkIn(ctx.pathParam("id"))));
    42	        app.post("/reservations/{id}/check-out", ctx -> reply(ctx, 200, service.checkOut(ctx.pathParam("id"))));
    43	        app.get("/reservations/{id}/document", ctx -> reply(ctx, 200, service.document(ctx.pathParam("id"))));
    44	        app.get("/messages", ctx -> reply(ctx, 200, service.sentMessages()));
    45	        app.get("/reports/occupancy", ctx ->
    46	                ctx.status(200).contentType(CSV).result(reports.occupancy(date(ctx.queryParam("date"), "date"))));
    47	        app.get("/reports/revenue", ctx ->
    48	                ctx.status(200).contentType(CSV).result(reports.revenue(month(ctx.queryParam("month")))));
    49	
    50	        app.exception(DomainException.class, (e, ctx) ->
    51	                reply(ctx, e.status(), Map.of("error", e.code(), "message", e.getMessage())));
    52	        app.exception(Exception.class, (e, ctx) -> {
    53	            e.printStackTrace();
    54	            reply(ctx, 500, Map.of("error", "INTERNAL_ERROR", "message", "Erro interno"));
    55	        });
    56	    }
    57	
    58	    private void reply(Context ctx, int status, Object body) {
    59	        try {
    60	            ctx.status(status).contentType("application/json").result(json.writeValueAsString(body));
    61	        } catch (JsonProcessingException e) {
    62	            throw new IllegalStateException(e);
    63	        }
    64	    }
    65	
    66	    private NewReservation parseNewReservation(String body) {
    67	        JsonNode node;
    68	        try {
    69	            node = json.readTree(body);
    70	        } catch (JsonProcessingException e) {
    71	            throw DomainException.invalidRequest("O corpo não é um JSON válido");
    72	        }
    73	        if (node == null || !node.isObject()) {
    74	            throw DomainException.invalidRequest("O corpo deve ser um objeto JSON");
    75	        }
    76	        int guests = integer(node, "guests");
    77	        return new NewReservation(
    78	                integer(node, "roomNumber"),
    79	                text(node, "guestName"),
    80	                text(node, "guestEmail"),
    81	                text(node, "guestCpf"),
    82	                date(text(node, "checkIn"), "checkIn"),
    83	                date(text(node, "checkOut"), "checkOut"),
    84	                guests,
    85	                ratePlan(text(node, "ratePlan")));
    86	    }
    87	
    88	    private static String text(JsonNode node, String field) {
    89	        JsonNode value = node.get(field);
    90	        if (value == null || !value.isTextual() || value.asText().isBlank()) {
    91	            throw DomainException.invalidRequest("Campo obrigatório ausente ou inválido: " + field);
    92	        }
    93	        return value.asText();
    94	    }
    95	
    96	    private static int integer(JsonNode node, String field) {
    97	        JsonNode value = node.get(field);
    98	        if (value == null || !value.isInt()) {
    99	            throw DomainException.invalidRequest("Campo obrigatório ausente ou inválido: " + field);
   100	        }
   101	        return value.asInt();
   102	    }
   103	
   104	    private static RatePlan ratePlan(String value) {
   105	        try {
   106	            return RatePlan.valueOf(value);
   107	        } catch (IllegalArgumentException e) {
   108	            throw DomainException.invalidRequest("Plano de tarifa inválido: " + value);
   109	        }
   110	    }
   111	
   112	    private static LocalDate date(String value, String field) {
   113	        if (value == null) throw DomainException.invalidRequest("Falta o parâmetro " + field);
   114	        try {
   115	            return LocalDate.parse(value);
   116	        } catch (DateTimeParseException e) {
   117	            throw DomainException.invalidRequest("Data inválida em " + field + ": use AAAA-MM-DD");
   118	        }
   119	    }
   120	
   121	    private static YearMonth month(String value) {
   122	        if (value == null) throw DomainException.invalidRequest("Falta o parâmetro month");
   123	        try {
   124	            return YearMonth.parse(value);
   125	        } catch (DateTimeParseException e) {
   126	            throw DomainException.invalidRequest("Mês inválido: use AAAA-MM");
   127	        }
   128	    }
   129	}
