     1	package br.com.marealta;
     2	
     3	import java.sql.Connection;
     4	import java.sql.SQLException;
     5	import java.util.ArrayList;
     6	import java.util.List;
     7	import java.util.function.BiFunction;
     8	import java.util.function.UnaryOperator;
     9	
    10	public class ReservationService {
    11	    private final Database db;
    12	    private final Rooms rooms;
    13	    private final ReservationRepository reservations;
    14	    private final MessageRepository messages;
    15	    private final List<ReservationListener> listeners;
    16	
    17	    public ReservationService(Database db, Rooms rooms, ReservationRepository reservations,
    18	                              MessageRepository messages, List<ReservationListener> listeners) {
    19	        this.db = db;
    20	        this.rooms = rooms;
    21	        this.reservations = reservations;
    22	        this.messages = messages;
    23	        this.listeners = List.copyOf(listeners);
    24	    }
    25	
    26	    public Reservation create(NewReservation request) {
    27	        Room room = rooms.get(request.roomNumber());
    28	        if (request.guests() > room.capacity()) {
    29	            throw DomainException.capacityExceeded(room.number(), room.capacity());
    30	        }
    31	        Pricing.Quote quote = Pricing.quote(room, request.checkIn(), request.checkOut(), request.ratePlan());
    32	        return db.inTransaction(c -> {
    33	            reservations.lockRoom(c, room.number());
    34	            if (reservations.isRoomBooked(c, room.number(), request.checkIn(), request.checkOut())) {
    35	                throw DomainException.roomUnavailable(room.number());
    36	            }
    37	            return reservations.insert(c, new Reservation(0, room.number(), request.guestName(),
    38	                    request.guestEmail(), request.guestCpf(), request.checkIn(), request.checkOut(),
    39	                    request.guests(), request.ratePlan(), quote.nights(), quote.subtotal(), quote.discount(),
    40	                    quote.total(), ReservationStatus.PENDING, Money.ZERO, null));
    41	        });
    42	    }
    43	
    44	    public Reservation get(String id) {
    45	        return db.inTransaction(c -> reservations.find(c, parseId(id))
    46	                .orElseThrow(() -> DomainException.reservationNotFound(id)));
    47	    }
    48	
    49	    public Reservation confirm(String id) {
    50	        return change(id, Reservation::confirm, (before, after) -> notify(after, ReservationListener::confirmed));
    51	    }
    52	
    53	    public Reservation cancel(String id) {
    54	        return change(id, Reservation::cancel, (before, after) -> before.status() == ReservationStatus.CONFIRMED
    55	                ? notify(after, ReservationListener::cancelledAfterConfirmation)
    56	                : List.of());
    57	    }
    58	
    59	    public Reservation checkIn(String id) {
    60	        return change(id, Reservation::checkInGuest, (before, after) -> List.of());
    61	    }
    62	
    63	    public Receipt checkOut(String id) {
    64	        Reservation r = change(id, Reservation::checkOutGuest, (before, after) -> List.of());
    65	        return Receipt.of(r, rooms.get(r.roomNumber()));
    66	    }
    67	
    68	    /** Segunda via do comprovante: só para reserva paga. */
    69	    public Receipt document(String id) {
    70	        Reservation r = get(id);
    71	        if (!r.status().isPaid()) {
    72	            throw DomainException.notAllowed("O comprovante só existe para reserva paga");
    73	        }
    74	        return Receipt.of(r, rooms.get(r.roomNumber()));
    75	    }
    76	
    77	    public List<Message> sentMessages() {
    78	        return db.inTransaction(messages::findAll);
    79	    }
    80	
    81	    /**
    82	     * Mudança de situação: trava a reserva, aplica a transição, grava e guarda as mensagens
    83	     * resultantes, tudo na mesma transação.
    84	     */
    85	    private Reservation change(String id, UnaryOperator<Reservation> transition,
    86	                               BiFunction<Reservation, Reservation, List<Message>> notifications) {
    87	        long reservationId = parseId(id);
    88	        return db.inTransaction(c -> {
    89	            Reservation before = reservations.findForUpdate(c, reservationId)
    90	                    .orElseThrow(() -> DomainException.reservationNotFound(id));
    91	            Reservation after = transition.apply(before);
    92	            reservations.update(c, after);
    93	            messages.saveAll(c, notifications.apply(before, after));
    94	            return after;
    95	        });
    96	    }
    97	
    98	    private List<Message> notify(Reservation r, BiFunction<ReservationListener, Reservation, List<Message>> event) {
    99	        List<Message> result = new ArrayList<>();
   100	        for (ReservationListener listener : listeners) result.addAll(event.apply(listener, r));
   101	        return result;
   102	    }
   103	
   104	    private long parseId(String id) {
   105	        try {
   106	            return Long.parseLong(id);
   107	        } catch (NumberFormatException e) {
   108	            throw DomainException.reservationNotFound(id);
   109	        }
   110	    }
   111	}
