     1	package br.com.marealta;
     2	
     3	import java.math.BigDecimal;
     4	import java.sql.Connection;
     5	import java.sql.Date;
     6	import java.sql.PreparedStatement;
     7	import java.sql.ResultSet;
     8	import java.sql.SQLException;
     9	import java.sql.Statement;
    10	import java.time.LocalDate;
    11	import java.util.ArrayList;
    12	import java.util.List;
    13	import java.util.Optional;
    14	
    15	/** Acesso às reservas; todas as operações rodam na transação da conexão recebida. */
    16	public class ReservationRepository {
    17	    private static final String COLUMNS = "id, room_number, guest_name, guest_email, guest_cpf, check_in, "
    18	            + "check_out, guests, rate_plan, nights, subtotal, discount, total, status, amount_paid, refund";
    19	
    20	    /** Serializa as reservas concorrentes do mesmo quarto até o fim da transação. */
    21	    public void lockRoom(Connection c, int roomNumber) throws SQLException {
    22	        try (PreparedStatement s = c.prepareStatement("SELECT pg_advisory_xact_lock(?)")) {
    23	            s.setLong(1, roomNumber);
    24	            s.execute();
    25	        }
    26	    }
    27	
    28	    /** Há reserva não cancelada do quarto em alguma noite de [checkIn, checkOut)? */
    29	    public boolean isRoomBooked(Connection c, int roomNumber, LocalDate checkIn, LocalDate checkOut)
    30	            throws SQLException {
    31	        try (PreparedStatement s = c.prepareStatement("SELECT 1 FROM reservations WHERE room_number = ? "
    32	                + "AND status <> 'CANCELLED' AND check_in < ? AND check_out > ? LIMIT 1")) {
    33	            s.setInt(1, roomNumber);
    34	            s.setDate(2, Date.valueOf(checkOut));
    35	            s.setDate(3, Date.valueOf(checkIn));
    36	            try (ResultSet rs = s.executeQuery()) {
    37	                return rs.next();
    38	            }
    39	        }
    40	    }
    41	
    42	    public Reservation insert(Connection c, Reservation r) throws SQLException {
    43	        try (PreparedStatement s = c.prepareStatement("INSERT INTO reservations (room_number, guest_name, "
    44	                + "guest_email, guest_cpf, check_in, check_out, guests, rate_plan, nights, subtotal, discount, "
    45	                + "total, status, amount_paid, refund) VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)",
    46	                Statement.RETURN_GENERATED_KEYS)) {
    47	            s.setInt(1, r.roomNumber());
    48	            s.setString(2, r.guestName());
    49	            s.setString(3, r.guestEmail());
    50	            s.setString(4, r.guestCpf());
    51	            s.setDate(5, Date.valueOf(r.checkIn()));
    52	            s.setDate(6, Date.valueOf(r.checkOut()));
    53	            s.setInt(7, r.guests());
    54	            s.setString(8, r.ratePlan().name());
    55	            s.setInt(9, r.nights());
    56	            s.setBigDecimal(10, r.subtotal());
    57	            s.setBigDecimal(11, r.discount());
    58	            s.setBigDecimal(12, r.total());
    59	            s.setString(13, r.status().name());
    60	            s.setBigDecimal(14, r.amountPaid());
    61	            s.setBigDecimal(15, r.refund());
    62	            s.executeUpdate();
    63	            try (ResultSet keys = s.getGeneratedKeys()) {
    64	                keys.next();
    65	                return r.withId(keys.getLong("id"));
    66	            }
    67	        }
    68	    }
    69	
    70	    public void update(Connection c, Reservation r) throws SQLException {
    71	        try (PreparedStatement s = c.prepareStatement(
    72	                "UPDATE reservations SET status = ?, amount_paid = ?, refund = ? WHERE id = ?")) {
    73	            s.setString(1, r.status().name());
    74	            s.setBigDecimal(2, r.amountPaid());
    75	            s.setBigDecimal(3, r.refund());
    76	            s.setLong(4, r.id());
    77	            s.executeUpdate();
    78	        }
    79	    }
    80	
    81	    /** Busca e trava a reserva até o fim da transação. */
    82	    public Optional<Reservation> findForUpdate(Connection c, long id) throws SQLException {
    83	        return query(c, "SELECT " + COLUMNS + " FROM reservations WHERE id = ? FOR UPDATE", id).stream().findFirst();
    84	    }
    85	
    86	    public Optional<Reservation> find(Connection c, long id) throws SQLException {
    87	        return query(c, "SELECT " + COLUMNS + " FROM reservations WHERE id = ?", id).stream().findFirst();
    88	    }
    89	
    90	    /** Reservas pagas e não canceladas que ocupam um quarto na noite, por número do quarto. */
    91	    public List<Reservation> occupying(Connection c, LocalDate night) throws SQLException {
    92	        return query(c, "SELECT " + COLUMNS + " FROM reservations WHERE status IN ('CONFIRMED','CHECKED_IN',"
    93	                + "'CHECKED_OUT') AND check_in <= ? AND check_out > ? ORDER BY room_number",
    94	                Date.valueOf(night), Date.valueOf(night));
    95	    }
    96	
    97	    /** Reservas que começam em [from, to) e deixaram dinheiro com a pousada. */
    98	    public List<Reservation> retainingStartingBetween(Connection c, LocalDate from, LocalDate to)
    99	            throws SQLException {
   100	        return query(c, "SELECT " + COLUMNS + " FROM reservations WHERE check_in >= ? AND check_in < ? "
   101	                + "AND amount_paid - COALESCE(refund, 0) > 0 ORDER BY check_in, id",
   102	                Date.valueOf(from), Date.valueOf(to));
   103	    }
   104	
   105	    private List<Reservation> query(Connection c, String sql, Object... params) throws SQLException {
   106	        try (PreparedStatement s = c.prepareStatement(sql)) {
   107	            for (int i = 0; i < params.length; i++) s.setObject(i + 1, params[i]);
   108	            try (ResultSet rs = s.executeQuery()) {
   109	                List<Reservation> result = new ArrayList<>();
   110	                while (rs.next()) result.add(read(rs));
   111	                return result;
   112	            }
   113	        }
   114	    }
   115	
   116	    private Reservation read(ResultSet rs) throws SQLException {
   117	        BigDecimal refund = rs.getBigDecimal("refund");
   118	        return new Reservation(
   119	                rs.getLong("id"),
   120	                rs.getInt("room_number"),
   121	                rs.getString("guest_name"),
   122	                rs.getString("guest_email"),
   123	                rs.getString("guest_cpf"),
   124	                rs.getObject("check_in", LocalDate.class),
   125	                rs.getObject("check_out", LocalDate.class),
   126	                rs.getInt("guests"),
   127	                RatePlan.valueOf(rs.getString("rate_plan")),
   128	                rs.getInt("nights"),
   129	                rs.getBigDecimal("subtotal"),
   130	                rs.getBigDecimal("discount"),
   131	                rs.getBigDecimal("total"),
   132	                ReservationStatus.valueOf(rs.getString("status")),
   133	                rs.getBigDecimal("amount_paid"),
   134	                refund);
   135	    }
   136	}

