    26	    public Reservation create(NewReservation request) {
    27	        Room room = rooms.get(request.roomNumber());
    28	        if (request.guests() > room.capacity()) {
    29	            throw DomainException.capacityExceeded(room.number(), room.capacity());
    30	        }
    31	        Pricing.Quote quote = Pricing.quote(room, request.checkIn(), request.checkOut(), request.ratePlan());
    32	        return db.inTransaction(c -> {
    33	            reservations.lockRoom(c, room.number());
    34	            if (reservations.isRoomBooked(c, room.number(), request.checkIn(), request.checkOut())) {
    35	                throw DomainException.roomUnavailable(room.number());
    36	            }
    37	            return reservations.insert(c, new Reservation(0, room.number(), request.guestName(),
    38	                    request.guestEmail(), request.guestCpf(), request.checkIn(), request.checkOut(),
    39	                    request.guests(), request.ratePlan(), quote.nights(), quote.subtotal(), quote.discount(),
    40	                    quote.total(), ReservationStatus.PENDING, Money.ZERO, null));
    41	        });
    42	    }
