     3	import java.math.BigDecimal;
     4	import java.time.LocalDate;
     5	import java.time.Month;
     6	
     7	public final class Pricing {
     8	    private static final BigDecimal HIGH_SEASON_FACTOR = new BigDecimal("1.20");
     9	
    10	    private Pricing() {}
    11	
    12	    public record Quote(int nights, BigDecimal subtotal, BigDecimal discount, BigDecimal total) {}
    13	
    14	    /** Alta temporada: de 15/12 ao fim de fevereiro e todo o mês de julho. */
    15	    public static boolean isHighSeason(LocalDate night) {
    16	        Month m = night.getMonth();
    17	        return m == Month.JANUARY || m == Month.FEBRUARY || m == Month.JULY
    18	                || (m == Month.DECEMBER && night.getDayOfMonth() >= 15);
    19	    }
    20	
    21	    public static BigDecimal nightPrice(Room room, LocalDate night) {
    22	        return isHighSeason(night)
    23	                ? Money.round(room.nightlyRate().multiply(HIGH_SEASON_FACTOR))
    24	                : room.nightlyRate();
    25	    }
    26	
    27	    public static Quote quote(Room room, LocalDate checkIn, LocalDate checkOut, RatePlan plan) {
    28	        BigDecimal subtotal = Money.ZERO;
    29	        int nights = 0;
    30	        for (LocalDate night = checkIn; night.isBefore(checkOut); night = night.plusDays(1)) {
    31	            subtotal = Money.round(subtotal.add(nightPrice(room, night)));
    32	            nights++;
    33	        }
    34	        BigDecimal discount = plan.discountOn(subtotal);
    35	        return new Quote(nights, subtotal, discount, Money.round(subtotal.subtract(discount)));
    36	    }
    37	}
