  7	import com.fasterxml.jackson.databind.ObjectMapper;
  8	import io.javalin.Javalin;
  9	import java.net.URI;
 10	import java.net.http.HttpClient;
 11	import java.net.http.HttpRequest;
 12	import java.net.http.HttpResponse;
 13	import java.sql.Connection;
 14	import java.sql.DriverManager;
 15	import java.sql.Statement;
 16	import java.util.UUID;
 17	import org.junit.jupiter.api.AfterAll;
 18	import org.junit.jupiter.api.BeforeAll;
 19	import org.junit.jupiter.api.Test;
 20	
 21	/** Roda contra o PostgreSQL de DB_URL, num schema próprio; é pulado se DB_URL não existir. */
 22	class ApiTest {
 23	    static final ObjectMapper JSON = new ObjectMapper()
 24	            .enable(com.fasterxml.jackson.databind.DeserializationFeature.USE_BIG_DECIMAL_FOR_FLOATS)
 25	            .setNodeFactory(com.fasterxml.jackson.databind.node.JsonNodeFactory.withExactBigDecimals(true));
 26	    static final HttpClient HTTP = HttpClient.newHttpClient();
 27	    static String baseUrl, rawUrl, schema, user, password;
 28	    static Database db;
 29	    static Javalin app;
 30	
 31	    @BeforeAll
 32	    static void start() throws Exception {
 33	        rawUrl = System.getenv("DB_URL");
 34	        assumeTrue(rawUrl != null, "DB_URL não definido");
 35	        user = System.getenv("DB_USER");
 36	        password = System.getenv("DB_PASSWORD");
 37	        schema = "test_" + UUID.randomUUID().toString().replace("-", "");
 38	        try (Connection c = DriverManager.getConnection(rawUrl, user, password); Statement s = c.createStatement()) {
 39	            s.execute("CREATE SCHEMA " + schema);
 40	        }
 41	        db = new Database(rawUrl + (rawUrl.contains("?") ? "&" : "?") + "currentSchema=" + schema, user, password);
 42	        app = App.create(db).start(0);
 43	        baseUrl = "http://localhost:" + app.port();
 44	    }
 45	
 46	    @AfterAll
 47	    static void stop() throws Exception {
 48	        if (app != null) app.stop();
 49	        if (db != null) db.close();
 50	        if (schema != null) {
 51	            try (Connection c = DriverManager.getConnection(rawUrl, user, password); Statement s = c.createStatement()) {
 52	                s.execute("DROP SCHEMA " + schema + " CASCADE");
 53	            }
 54	        }
 55	    }
 56	
 57	    record Res(int status, String contentType, String body) {
 58	        JsonNode json() throws Exception { return JSON.readTree(body); }
 59	    }
 60	
 61	    static Res call(String method, String path, String body) throws Exception {
 62	        HttpRequest.Builder b = HttpRequest.newBuilder(URI.create(baseUrl + path));
 63	        b.method(method, body == null ? HttpRequest.BodyPublishers.noBody() : HttpRequest.BodyPublishers.ofString(body));
 64	        HttpResponse<String> r = HTTP.send(b.build(), HttpResponse.BodyHandlers.ofString());
 65	        return new Res(r.statusCode(), r.headers().firstValue("content-type").orElse(""), r.body());
 66	    }
 67	
 68	    static String booking(int room, String in, String out, int guests, String plan) {
 69	        return """
 70	                {"roomNumber":%d,"guestName":"Carla Dias","guestEmail":"carla@example.com","guestCpf":"111.222.333-44",
 71	                 "checkIn":"%s","checkOut":"%s","guests":%d,"ratePlan":"%s"}""".formatted(room, in, out, guests, plan);
 72	    }
 73	
 74	    static long create(int room, String in, String out, int guests, String plan) throws Exception {
 75	        Res r = call("POST", "/reservations", booking(room, in, out, guests, plan));
 76	        assertEquals(201, r.status(), r.body());
 77	        return r.json().get("id").asLong();
 78	    }
 79	
 80	    static void assertError(Res r, int status, String code) throws Exception {
 81	        assertEquals(status, r.status(), r.body());
 82	        assertEquals(code, r.json().get("error").asText());
 83	    }
 84	
 85	    @Test
 86	    void listsRooms() throws Exception {
 87	        JsonNode rooms = call("GET", "/rooms", null).json();
 88	        assertEquals(5, rooms.size());
 89	        assertEquals(301, rooms.get(4).get("number").asInt());
 90	        assertEquals("SUITE", rooms.get(4).get("type").asText());
 91	        assertEquals(4, rooms.get(4).get("capacity").asInt());
 92	        assertEquals("579.90", rooms.get(4).get("nightlyRate").decimalValue().toPlainString());
 93	    }
 94	
 95	    @Test
 96	    void validatesRequests() throws Exception {
 97	        assertError(call("POST", "/reservations", "não é json"), 400, "INVALID_REQUEST");
 98	        assertError(call("POST", "/reservations", "{}"), 400, "INVALID_REQUEST");
 99	        assertError(call("POST", "/reservations", booking(101, "2030-05-10", "2030-05-10", 1, "STANDARD")), 400, "INVALID_REQUEST");
100	        assertError(call("POST", "/reservations", booking(101, "2030-05-10", "2030-05-12", 0, "STANDARD")), 400, "INVALID_REQUEST");
101	        assertError(call("POST", "/reservations", booking(101, "10/05/2030", "2030-05-12", 1, "STANDARD")), 400, "INVALID_REQUEST");
102	        assertError(call("POST", "/reservations", booking(101, "2030-05-10", "2030-05-12", 1, "VIP")), 400, "INVALID_REQUEST");
103	        assertError(call("POST", "/reservations", booking(999, "2030-05-10", "2030-05-12", 1, "STANDARD")), 404, "ROOM_NOT_FOUND");
104	        assertError(call("POST", "/reservations", booking(101, "2030-05-10", "2030-05-12", 3, "STANDARD")), 422, "CAPACITY_EXCEEDED");
