184	        long nr = create(102, "2032-03-20", "2032-03-22", 2, "NON_REFUNDABLE");
185	        call("POST", "/reservations/" + nr + "/confirmation", null);
186	        mid = call("GET", "/messages", null).json().size();
187	        JsonNode kept = call("POST", "/reservations/" + nr + "/cancellation", null).json();
188	        assertEquals("0.00", kept.get("refund").decimalValue().toPlainString());
189	        assertEquals(mid + 1, call("GET", "/messages", null).json().size());
190	
191	        String revenue = call("GET", "/reports/revenue?month=2032-03", null).body();
192	        assertEquals("reservation,room,check_in,check_out,status,amount\n"
193	                + nr + ",102,2032-03-20,2032-03-22,CANCELLED,424.83\n"
194	                + "total,424.83\n", revenue);
195	    }
