296	    @Test
297	    void seasonBoundaries() {
298	        assertFalse(Pricing.isHighSeason(LocalDate.parse("2027-12-14")));
299	        assertTrue(Pricing.isHighSeason(LocalDate.parse("2027-12-15")));
300	        assertTrue(Pricing.isHighSeason(LocalDate.parse("2028-02-29")));
301	        assertFalse(Pricing.isHighSeason(LocalDate.parse("2028-03-01")));
302	        assertFalse(Pricing.isHighSeason(LocalDate.parse("2027-06-30")));
303	        assertTrue(Pricing.isHighSeason(LocalDate.parse("2027-07-31")));
304	        assertFalse(Pricing.isHighSeason(LocalDate.parse("2027-08-01")));
305	    }
